import{_ as e,o as d,c as o,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"Comparison","description":"","frontmatter":{},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md","lastUpdated":1795529849000}'),a={name:"comparison.md"};function r(n,t,c,i,h,l){return d(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h1><p>These libraries test some of the same methods. They do not do the same job. Versions below were current when this page was written in November 2026. A later release can move a cell. This page does not repeat the coverage numbers from the 2016 comparison. Those were measured with JaCoCo 0.7.7 on four generated classes and are not a result for the current line.</p><table tabindex="0"><thead><tr><th></th><th>pojo-tester</th><th>EqualsVerifier</th><th>OpenPojo</th><th>MeanBean</th><th>JavaBean Tester</th><th>bean-matchers</th></tr></thead><tbody><tr><td>Coordinates</td><td><code>pl.pojo:pojo-tester</code></td><td><code>nl.jqno.equalsverifier:equalsverifier</code></td><td><code>com.openpojo:openpojo</code></td><td><code>com.github.meanbeanlib:meanbean</code></td><td><code>com.github.hazendaz:javabean-tester</code></td><td><code>com.google.code.bean-matchers:bean-matchers</code></td></tr><tr><td>Version</td><td><code>0.8.0-SNAPSHOT</code>, last release <code>0.7.6</code> (2017)</td><td><code>4.5.2</code> (August 2026)</td><td><code>0.9.1</code></td><td><code>3.0.0-M9</code> (2020)</td><td><code>2.12.2</code></td><td><code>0.14</code></td></tr><tr><td>License</td><td>LGPL-3.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>Apache-2.0</td><td>BSD-3-Clause</td></tr><tr><td>Java</td><td>bytecode 8</td><td>8, with newer lines</td><td>8 and newer</td><td>8</td><td>17</td><td>8</td></tr><tr><td><code>equals</code></td><td>yes</td><td>yes, the contract</td><td>only through its own <code>BusinessIdentity</code></td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>hashCode</code></td><td>yes</td><td>yes, the contract</td><td>only through <code>BusinessIdentity</code></td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>toString</code></td><td>yes</td><td>no</td><td>only through <code>BusinessIdentity</code></td><td>yes, in the 3.x line</td><td>yes</td><td>yes</td></tr><tr><td>getters and setters</td><td>yes</td><td>no</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>constructors</td><td>yes</td><td>no</td><td>no</td><td>no</td><td>yes</td><td>a no-args constructor</td></tr><tr><td>Production code stays untouched</td><td>yes</td><td>yes</td><td>no, for equals</td><td>yes</td><td>yes</td><td>yes</td></tr></tbody></table><h2 id="how-they-differ" tabindex="-1">How they differ <a class="header-anchor" href="#how-they-differ" aria-label="Permalink to &quot;How they differ&quot;">​</a></h2><p><strong>EqualsVerifier</strong> is the library to use when the question is only whether <code>equals</code> and <code>hashCode</code> meet the contract. It is strict about symmetry, inheritance, significant fields and the usual shortcuts, and it understands records. It does not call getters or setters. pojo-tester is not a substitute for that check.</p><p><strong>OpenPojo</strong> validates structure with rules (<code>SetterMustExistRule</code>, and so on) and can test getters and setters. Its <code>equals</code>, <code>hashCode</code> and <code>toString</code> support expects the class to delegate to <code>BusinessIdentity</code> and to mark fields with <code>@BusinessKey</code>. A class that already has its own implementations is not what that tester runs.</p><p><strong>MeanBean</strong> tests getters, setters, <code>equals</code> and <code>hashCode</code>. The original 2.x line is the one the 2016 page compared. The 3.x line, published as milestones through <code>3.0.0-M9</code>, adds <code>toString</code>, fluent setters and a package scan. There is no stable 3.0.0.</p><p><strong>JavaBean Tester</strong> covers constructors, getters, setters, <code>equals</code>, <code>hashCode</code>, <code>toString</code> and <code>Serializable</code>. It requires Java 17, so it is not an option for a Java 8 test suite.</p><p><strong>bean-matchers</strong> expresses the same checks as Hamcrest matchers, including a no-args constructor. The last release is <code>0.14</code>. The project is not maintained.</p><p>pojo-tester runs the six testers against the methods the class already has. It does not ask for an annotation, and one assertion can also select fields, a constructor, a supplier and a prefix. It will not catch every contract mistake EqualsVerifier catches. Use both when a class has a hand-written <code>equals</code> and also has getters.</p><h2 id="earlier-libraries" tabindex="-1">Earlier libraries <a class="header-anchor" href="#earlier-libraries" aria-label="Permalink to &quot;Earlier libraries&quot;">​</a></h2><p>The 2016 page also listed SmartUnit, testUtils and testUtil. They are not maintained and are not in the table. A project that still builds against one of them has no reason to stay there for a new test.</p>',12)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
